}#stage .pw-sc.on{ opacity:1; }#stage .pw-world{ flex:1; min-height:0; display:flex; flex-direction:column; gap:10px; }#stage .pw-row{ width:100%; display:flex; gap:16px; flex-shrink:0; }#stage .pw-tr{
  flex:1; min-width:0; height:250px; display:flex; flex-direction:column; align-items:center;
