}#stage .pw-chip.big{ margin-left:auto; flex-shrink:0; padding:12px 22px; font-size:25px; }#stage .pw-chip.ok{ background:rgba(63,185,80,.14); border-color:rgba(63,185,80,.5); color:var(--success); }#stage .pw-chip.bad{ background:rgba(244,74,106,.14); border-color:rgba(244,74,106,.5); color:var(--danger); }#stage .pw-chip.warn{ background:rgba(240,166,74,.14); border-color:rgba(240,166,74,.5); color:var(--warn); }#stage .pw-final{ height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:28px; text-align:center; }#stage .pw-badge{
