var PW = window.__PW || (window.__PW = {});
// Column centres and row centres, in % of the scene.
PW.X = [27, 73];
PW.Y = { top: 14, hook: 42, order: 68 };

PW.scene = function(id){ MSD.cls('.pw-sc', 'on', false); MSD.cls('#pw-sc-' + id, 'on', true); };

PW.strip = function(label, text, tone){
  MSD.cls('#pw-strip', 'bad', tone === 'bad');
  MSD.cls('#pw-strip', 'good', tone === 'good');
  MSD.q('#pw-strip-l').textContent = label;
  MSD.q('#pw-strip-t').textContent = text;
};

PW.tr = function(i, text, tone){
  MSD.q('#pw-tr-t-' + i).textContent = text;
  ['bad','good','warn'].forEach(function(c){ MSD.cls('#pw-tr-' + i, c, tone === c); });
};

PW.ar = function(row, i, tone){
  ['live','bad','ok'].forEach(function(c){ MSD.cls('#pw-a' + row + '-' + i, c, tone === c); });
};

PW.box = function(sel, tone){ ['live','bad','ok','warn'].forEach(function(c){ MSD.cls(sel, c, tone === c); }); };
PW.chip = function(sel, text, tone){
  var v = MSD.q(sel); v.textContent = text;
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, tone === c); });
};

PW.hook = function(state, tone, sub){
  PW.box('#pw-hook', tone);
  PW.chip('#pw-hook-v', state, tone === 'live' ? '' : tone);
  MSD.q('#pw-h-s').textContent = sub || 'your server hears the result';
  MSD.q('#pw-h-n').textContent = 'Payment webhook';
};
PW.name = function(text){ MSD.q('#pw-h-n').textContent = text; };
PW.order = function(state, tone, sub){
  PW.box('#pw-order', tone);
  PW.chip('#pw-o-v', state, tone === 'live' ? '' : tone);
  MSD.q('#pw-o-s').textContent = sub || 'in Azure SQL';
};

// Something travelling between two rows. The app and the gateway sit in
// two columns; the webhook and the order are one centred row each.
PW.go = function(col, fromRow, toRow, n){
  var fx = fromRow === 'top' ? PW.X[col] : 50;
  var tx = toRow === 'top' ? PW.X[col] : 50;
  MSD.particles('#pw-scene', { from:{ x:fx, y:PW.Y[fromRow] }, to:{ x:tx, y:PW.Y[toRow] }, count:n || 5, duration:650, spread:18 });
};

PW.reset = function(){
  PW.scene('world');
  PW.tr(1, 'checking out', ''); PW.tr(2, 'waiting', '');
  PW.ar(1, 1, ''); PW.ar(1, 2, ''); PW.ar(2, 1, '');
  PW.hook('idle', '');
  PW.order('PendingPayment', '');
};

PW.reset();
PW.strip('SUNDAY LUNCH', 'A customer pays by UPI.', '');
MSD.after(500, function(){ MSD.punch('#pw-order', 2); MSD.sfx.focus(); });
MSD.after(1300, function(){ PW.tr(1, 'in the UPI app', 'warn'); MSD.punch('#pw-tr-1', 3); MSD.sfx.pop(); });
MSD.after(2200, function(){ PW.ar(1, 1, 'live'); PW.go(0, 'top', 'top', 4); });
MSD.after(2800, function(){ PW.tr(2, '₹414 captured ✓', 'good'); MSD.punch('#pw-tr-2', 4); MSD.sfx.lock(); });
MSD.after(3600, function(){ PW.strip('PAID', 'The money has left the account.', 'good'); });

